'use strict';
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'..');
const parserPath=path.join(root,'engines','parser-semantics.js');
const testPath=path.join(root,'tests','parser-round-scope-only-20260825.cjs');
let parser=fs.readFileSync(parserPath,'utf8');
const oldSplitter="  function splitRoundBody(body){const out=[];let buf='',depth=0;const flush=()=>{const v=clean(buf);if(v)out.push(v);buf=''};for(const ch of String(body||'')){if(ch==='('){depth++;buf+=ch;continue}if(ch===')'){depth=Math.max(0,depth-1);buf+=ch;continue}if(depth===0&&(ch===','||ch===';'||ch==='+'||ch==='\\n')){flush();continue}buf+=ch}flush();return out}\n";
const newSplitter="  function roundChildStart(value){return /^\\s*(?:\\d{1,2}\\s*(?:x|×|✕|\\*)\\s*\\d{1,4}(?:\\.5)?\\b|\\d{2,4}(?:\\.5)?\\b)/i.test(String(value||''))}\n  function splitRoundBody(body){const src=String(body||''),out=[];let buf='',depth=0;const flush=()=>{const v=clean(buf);if(v)out.push(v);buf=''};for(let i=0;i<src.length;i++){const ch=src[i];if(ch==='('){depth++;buf+=ch;continue}if(ch===')'){depth=Math.max(0,depth-1);buf+=ch;continue}if(depth===0){const after=src.slice(i+1),simple=ch===','||ch===';'||ch==='+'||ch==='&'||ch==='\\n';if(simple&&roundChildStart(after)){flush();continue}if(ch==='/'&&roundChildStart(after)){const hit=clean(after).match(/^(?:(\\d{1,2})\\s*(?:x|×|✕|\\*)\\s*)?(\\d{2,4}(?:\\.5)?)/i);if(hit&&(hit[1]||Number(hit[2])>=100)){flush();continue}}const word=src.slice(i).match(/^\\s+(?:and|then|plus)\\s+/i);if(word&&roundChildStart(src.slice(i+word[0].length))){flush();i+=word[0].length-1;continue}}buf+=ch}flush();return out}\n";
if(!parser.includes(oldSplitter))throw new Error('expected round splitter not found');
parser=parser.replace(oldSplitter,newSplitter);
const oldNormal="  function normaliseRoundChild(value){return clean(value).replace(/^(\\d{2,4}(?:\\.5)?)(?=[A-Za-z])/,'$1 ')}\n";
const newNormal="  function normaliseRoundChild(value){return clean(value).replace(/(\\d)\\s*\\*\\s*(\\d)/g,'$1 x $2').replace(/^(\\d{2,4}(?:\\.5)?)(?=[A-Za-z])/,'$1 ')}\n";
if(!parser.includes(oldNormal))throw new Error('expected child normaliser not found');
parser=parser.replace(oldNormal,newNormal);
const oldOuter="const raw=lines[i],m=raw.match(/^(\\s*)(\\d{1,2})\\s*(?:x|×|✕)\\s*\\(\\s*(.*)$/i);";
const newOuter="const raw=lines[i],m=raw.match(/^(\\s*)(\\d{1,2})\\s*(?:(?:x|×|✕|\\*)\\s*|rounds?\\s*(?:of\\s*)?)\\(\\s*(.*)$/i);";
if(!parser.includes(oldOuter))throw new Error('expected outer repeat matcher not found');
parser=parser.replace(oldOuter,newOuter).replace('v4-parser-semantics-final-20260825d-round-plus-scope','v4-parser-semantics-final-20260825e-notation-family');
fs.writeFileSync(parserPath,parser);
let test=fs.readFileSync(testPath,'utf8');
const oldCases="verify(`MAIN SET\\n3 x (5 x 100 Threshold + 200 Easy)`,'literal-plus-sign');\nverify(`MAIN SET\\n3 x (5 x 100 Threshold, 200 Easy)`,'single-line');\nverify(`MAIN SET\\n3 x (\\n5 x 100 Threshold\\n200 Easy\\n)`,'multi-line');\n";
const newCases="const variants=[['plus','MAIN SET\\n3 x (5 x 100 Threshold + 200 Easy)'],['comma','MAIN SET\\n3 x (5 x 100 Threshold, 200 Easy)'],['semicolon','MAIN SET\\n3 x (5 x 100 Threshold; 200 Easy)'],['and','MAIN SET\\n3 x (5 x 100 Threshold and 200 Easy)'],['then','MAIN SET\\n3 x (5 x 100 Threshold then 200 Easy)'],['ampersand','MAIN SET\\n3 x (5 x 100 Threshold & 200 Easy)'],['slash','MAIN SET\\n3 x (5 x 100 Threshold / 200 Easy)'],['unicode','MAIN SET\\n3 × (5 × 100 Threshold + 200 Easy)'],['tight','MAIN SET\\n3x(5x100 Threshold+200 Easy)'],['capital-x','MAIN SET\\n3 X (5 X 100 Threshold + 200 Easy)'],['star','MAIN SET\\n3 * (5 * 100 Threshold + 200 Easy)'],['rounds-of','MAIN SET\\n3 rounds of (5 x 100 Threshold + 200 Easy)'],['rounds','MAIN SET\\n3 rounds (5 x 100 Threshold + 200 Easy)'],['multi-line','MAIN SET\\n3 x (\\n5 x 100 Threshold\\n200 Easy\\n)']];\nfor(const [label,source] of variants)verify(source,label);\nconst composition=global.MSOS4.parser.parse('MAIN SET\\n3 x (5 x 100 Threshold 25 drill / 75 swim + 200 Easy)',{id:'slash-composition'});assert.equal(S.total(composition),2100,'slash inside 100 composition must not create phantom metres');\n";
if(!test.includes(oldCases))throw new Error('expected regression cases not found');
test=test.replace(oldCases,newCases);
fs.writeFileSync(testPath,test);
console.log('ROUND_NOTATION_FAMILY_HARDENED');
